  'pricing.faq.trialQ': 'Wie funktioniert die 7-tägige kostenlose Testversion?',
  'pricing.faq.trialA': 'Jedes neue Konto erhält automatisch eine 7-tägige kostenlose Testphase – kein Code erforderlich. Sie müssen Ihre Kartendaten eingeben, aber 7 Tage lang wird nichts berechnet. Nach 7 Tagen beginnt das Abonnement automatisch. Während der Testphase können Sie jederzeit kündigen.',
