  'landing.hl.comingSoon': 'Demnächst',
  'landing.ctaBannerDesc': 'Starten Sie Ihre kostenlose Testversion heute und erleben Sie, wie intelligenteres Nachhilfe-Management Abläufe optimiert, die Effizienz steigert und das Wachstum fördert.',
  'landing.blogTitle': 'Unser Blog — Einblicke für intelligentere Nachhilfe',
  'landing.blogSeeAll': 'Alle Artikel anzeigen',
  'landing.blogFeaturedDate': 'Empfohlen · 2025',
  'landing.blogFeatured': 'Wie intelligente Planung den Umsatz von Nachhilfelehrern in nur einem Quartal um 30 % steigerte',
  'landing.blogPost1Date': '2025',
  'landing.blogPost1': 'Die 5 häufigsten Fehler von Nachhilfelehrern bei der Schülerverwaltung',
  'landing.blogPost2': 'Fallstudie: Wie Nachhilfelehrer ihren Betrieb mit Tutlio-Automatisierung optimierten',
  'landing.footerCtaDesc': 'Starten Sie Ihre kostenlose Testversion heute und erleben Sie, wie Tutlio die Effizienz verbessern, die Zusammenarbeit fördern und das Geschäftswachstum antreiben kann.',
  'landing.footerProduct': 'Produkt',
  'landing.footerGetStarted': 'Loslegen',
  'landing.footerSolutions': 'Lösungen',
  'landing.footerResources': 'Ressourcen',
  'landing.footerCompany': 'Unternehmen',
  'landing.faq.whatIsQ': 'Was ist Tutlio?',
  'landing.faq.whatIsA': 'Tutlio ist eine Verwaltungsplattform für Nachhilfe, die selbstständigen Nachhilfelehrern und Schulen hilft, Stundenpläne, Zahlungen, die Kommunikation mit Schülern und den Unterrichtsverlauf an einem Ort zu verwalten.',
  'landing.faq.whoForQ': 'Für wen ist Tutlio?',
  'landing.faq.whoForA': 'Tutlio ist für selbstständige Nachhilfelehrer, Musiklehrer, Sprachlehrer, Mathematiklehrer, Nachhilfeschulen und Bildungszentren konzipiert.',
  'landing.faq.waitlistQ': 'Wie funktioniert die Warteliste?',
  'landing.faq.waitlistA': 'Wenn ein Schüler eine Stunde absagt, wird der freigewordene Termin automatisch den Schülern auf der Warteliste angeboten. Wer zuerst bestätigt, erhält den Platz.',
  'landing.faq.freeTrialQ': 'Gibt es eine kostenlose Testversion?',
  'landing.faq.freeTrialA': 'Ja! Jedes neue Konto erhält automatisch 7 Tage gratis — kein Code nötig. Keine Gebühren während der Testphase.',
  'landing.faq.languagesQ': 'Welche Sprachen unterstützt Tutlio?',
  "landing.faq.languagesA": "Tutlio ist in {count} Sprachen verfügbar: {languages}.",
  'landing.faqTitle': 'Häufig gestellte Fragen',
  'feature.calendar.pageTitle': 'Intelligenter Nachhilfe-Kalender und Planungssoftware',
  'feature.calendar.pageDesc': 'Lassen Sie Schüler selbst Stunden aus Ihren verfügbaren Zeiten buchen. Der intelligente Kalender von Tutlio verwaltet automatisch wiederkehrende Stunden, Pausen und Buchungsfristen.',
  'feature.calendar.detailsTitle': 'So funktioniert der intelligente Kalender',
  'feature.calendar.selfBooking': 'Selbstbuchung für Schüler',
  'feature.calendar.selfBookingDesc': 'Legen Sie Ihre verfügbaren Zeitfenster fest und lassen Sie Schüler direkt buchen – ohne zeitaufwendige Nachrichtenabstimmung.',
  'feature.calendar.recurring': 'Wiederkehrende Stunden',
  'feature.calendar.recurringDesc': 'Erstellen Sie wöchentlich oder zweiwöchentlich wiederkehrende Stunden, die automatisch in Ihrem Kalender und im Kalender des Schülers erscheinen.',
  'feature.calendar.breaks': 'Pausenverwaltung',
  'feature.calendar.breaksDesc': 'Legen Sie automatische Pausen zwischen den Stunden fest, damit es nicht zu Doppelbuchungen ohne Erholungszeit kommt.',
  'feature.calendar.deadlines': 'Buchungsfristen',
  'feature.calendar.deadlinesDesc': 'Legen Sie fest, wie weit im Voraus Schüler buchen müssen (z. B. 24 Stunden vorher).',
  'feature.calendar.faq.howBookQ': 'Wie buchen Schüler Stunden?',
  'feature.calendar.faq.howBookA': 'Schüler erhalten einen persönlichen Buchungslink, über den sie Ihre verfügbaren Zeiten sehen und direkt buchen können. Sie legen fest, welche Zeiten verfügbar sind und wie weit im Voraus gebucht werden kann.',
  'feature.calendar.faq.groupLessonsQ': 'Kann ich Gruppenstunden planen?',
  'feature.calendar.faq.groupLessonsA': 'Ja! Sie können Zeitfenster für Gruppenstunden erstellen, für die sich mehrere Schüler zur selben Zeit anmelden können.',
  'feature.calendar.faq.mobileCalendarQ': 'Funktioniert der Kalender auf dem Handy?',
  'feature.calendar.faq.mobileCalendarA': 'Ja, Tutlio funktioniert auf jedem Gerät – Computer, Tablet oder Smartphone. Für einen schnellen Zugriff können Sie Tutlio außerdem als Progressive Web App installieren.',
  'feature.waitlist.pageTitle': 'Warteliste — keine Einnahmen mehr durch Absagen verlieren',
  'feature.waitlist.pageDesc': 'Wenn ein Schüler absagt, bietet Tutlio den freigewordenen Termin automatisch Schülern auf der Warteliste an. So werden Lücken sofort gefüllt und Ihr Stundenplan bleibt ausgelastet.',
  'feature.waitlist.detailsTitle': 'So funktioniert die Warteliste',
  'feature.waitlist.autoFill': 'Automatische Platzbelegung',
  'feature.waitlist.autoFillDesc': 'Wird eine Stunde abgesagt, benachrichtigt das System sofort die Schüler auf der Warteliste, für die diese Zeit geeignet ist. Wer zuerst bestätigt, erhält den Termin.',
  'feature.waitlist.notifications': 'Sofortige Benachrichtigungen',
  'feature.waitlist.notificationsDesc': 'Wartelisten-Schüler erhalten sofortige E-Mail-Benachrichtigungen, wenn ihr bevorzugter Termin frei wird.',
  'feature.waitlist.priority': 'Prioritätswarteschlange',
  'feature.waitlist.priorityDesc': 'Schüler treten der Warteliste für bestimmte Zeiten bei. Die Warteschlange gewährleistet fairen Zugang.',
  'feature.waitlist.revenue': 'Einnahmenschutz',
  'feature.waitlist.revenueDesc': 'Verlieren Sie keine Einnahmen mehr durch Absagen. Die Warteliste sorgt dafür, dass frei gewordene Termine schnell neu belegt werden und Sie Ihre Unterrichtszeit optimal nutzen.',
  'feature.waitlist.faq.howWorksQ': 'Wie füllt die Warteliste abgesagte Termine?',
  'feature.waitlist.faq.howWorksA': 'Bei einer Absage prüft das System die Warteliste und sendet ein Angebot. Der erste Bestätigende erhält die Stunde.',
  'feature.waitlist.faq.studentLimitQ': 'Gibt es ein Schülerlimit auf der Warteliste?',
  'feature.waitlist.faq.studentLimitA': 'Nein, es gibt keine Begrenzung. Beliebig viele Schüler können sich für jedes Zeitfenster auf die Warteliste setzen.',
  'feature.waitlist.faq.automaticQ': 'Ist der Prozess vollautomatisch?',
  'feature.waitlist.faq.automaticA': 'Ja! Nach der Einrichtung läuft der gesamte Prozess – von der Absage über die Benachrichtigung bis zur erneuten Buchung – vollautomatisch. Sie müssen nichts weiter tun.',
  'feature.payments.pageTitle': 'Zahlungsabwicklung und Rechnungsstellung für Nachhilfelehrer',
  'feature.payments.pageDesc': 'Akzeptieren Sie Schülerzahlungen über Stripe, verfolgen Sie Zahlungen, erstellen Sie Rechnungen und sehen Sie monatliche Einnahmenübersichten.',
  'feature.payments.detailsTitle': 'Zahlungsfunktionen',
  'feature.payments.stripe': 'Stripe-Integration',
