  'feature.payments.packagesDesc': 'Verkaufen Sie Stundenpakete (z. B. 10 Stunden mit Rabatt) und verfolgen Sie die Nutzung automatisch.',
  'feature.payments.faq.methodsQ': 'Welche Zahlungsmethoden werden unterstützt?',
  'feature.payments.faq.methodsA': 'Tutlio nutzt Stripe, das alle gängigen Kredit- und Debitkarten, Apple Pay, Google Pay und Banküberweisungen unterstützt.',
  'feature.payments.faq.feesQ': 'Erhebt Tutlio zusätzliche Gebühren?',
  'feature.payments.faq.feesA': 'Tutlio erhebt keine zusätzlichen Gebühren. Es gelten die Standard-Stripe-Gebühren.',
  'feature.payments.faq.invoiceAutoQ': 'Können Rechnungen automatisch erstellt werden?',
  'feature.payments.faq.invoiceAutoA': 'Ja, Sie können Rechnungen pro Schüler oder Zeitraum erstellen und direkt über die Plattform versenden.',
  'feature.reminders.pageTitle': 'Automatische Stundenerinnerungen für Nachhilfelehrer',
  'feature.reminders.pageDesc': 'Senden Sie automatische E-Mail-Erinnerungen vor Stunden, Nachbesprechungen und Zahlungserinnerungen.',
  'feature.reminders.detailsTitle': 'Erinnerungstypen',
  'feature.reminders.beforeLesson': 'Erinnerungen vor der Stunde',
  'feature.reminders.beforeLessonDesc': 'Schüler erhalten vor der nächsten Stunde automatisch eine Erinnerungs-E-Mail. Den Versandzeitpunkt legen Sie fest, zum Beispiel 24 oder 1 Stunde vorher.',
  'feature.reminders.afterLesson': 'Nachbesprechung',
  'feature.reminders.afterLessonDesc': 'Senden Sie automatische E-Mails nach Stunden mit Notizen oder Hausaufgaben.',
  'feature.reminders.paymentDue': 'Zahlungserinnerungen',
  'feature.reminders.paymentDueDesc': 'Automatische Benachrichtigungen über überfällige Zahlungen, damit Sie Schülern nicht selbst wegen ausstehender Beträge nachlaufen müssen.',
  'feature.reminders.customTiming': 'Anpassbare Zeiten',
  'feature.reminders.customTimingDesc': 'Legen Sie genau fest, wann die einzelnen Erinnerungstypen gesendet werden, passend zu Ihrem Arbeitsablauf und Ihren Präferenzen.',
  'feature.reminders.faq.channelsQ': 'Wie werden Erinnerungen gesendet?',
  'feature.reminders.faq.channelsA': 'Erinnerungen werden per E-Mail automatisch gemäß Ihrem konfigurierten Zeitplan gesendet.',
  'feature.reminders.faq.customizeQ': 'Kann ich die Nachrichten anpassen?',
  'feature.reminders.faq.customizeA': 'Das System sendet professionelle, lokalisierte Erinnerungen in der Sprache des Schülers. Die Inhalte sind auf Klarheit und eine eindeutige Handlungsaufforderung optimiert.',
