  'schoolsLanding.hl.whiteLabelDesc': 'Verwenden Sie das Logo und die Farben Ihrer Einrichtung — Schüler und Eltern sehen vertrautes Schulbranding im Portal.',
  'schoolsLanding.hl.whiteboard': 'Whiteboard',
