  'schoolsLanding.ctaBannerTitle': 'Bereit, Ihre Schule zu digitalisieren?',
  'schoolsLanding.ctaBannerDesc': 'Kontaktieren Sie unser Team und erfahren Sie, wie Tutlio Schools Ihre Verwaltung optimieren, die Effizienz steigern und Wachstum unterstützen kann.',
  'schoolsLanding.ctaBannerBtn': 'Kontaktieren Sie uns',
