  'orgTutorPolicy.title': 'Interne Regeln für Lehrkräfte',
  'orgTutorPolicy.intro': 'Bitte lesen Sie die internen Regeln der Organisation, bevor Sie die Plattform nutzen.',
  'orgTutorPolicy.acceptBtn': 'Verstanden',
  'orgTutorPolicy.viewBtn': 'Interne Regeln ansehen',
  'orgTutorPolicy.s1Title': '1. Allgemeine Bestimmungen',
  'orgTutorPolicy.s1Body': 'Diese Regeln regeln Ihre Nutzung der Tutlio-Plattform (die „Plattform“) als Lehrerin/Lehrer oder Nachhilfelehrkraft (die „Lehrkraft“). Sie wurden von der Bildungsagentur, Schule oder dem Nachhilfezentrum, das Sie vertreten (die „Organisation“), eingeladen, die Plattform zu nutzen. Die Plattform wird technisch von MB Tutlio betrieben und gewartet. Durch die Nutzung Ihres Kontos stimmen Sie diesen Regeln und der Datenschutzrichtlinie zu.',
  'orgTutorPolicy.s2Title': '2. Kontoverwaltung und Stundenpläne',
  'orgTutorPolicy.s2Intro': 'Die Plattform ist so konzipiert, dass Sie keine Zeit mit der Abstimmung von Unterrichtszeiten mit Schülern verbringen müssen.',
  'orgTutorPolicy.s2Link': 'Einzigartiger Link: Ihnen wird ein persönlicher Buchungslink für Unterrichtsstunden zugewiesen (basierend auf den Fächern, die Sie unterrichten), den Schüler zur Terminvereinbarung nutzen.',
  'orgTutorPolicy.s2Calendar': 'Kalender-Synchronisierung: Ihre Verfügbarkeit hängt direkt von Ihrer Google-Calendar-Integration ab (bidirektionale Synchronisierung). Sie sind persönlich dafür verantwortlich, dass die in Ihrem Kalender angezeigte freie Zeit korrekt und aktuell ist. Die Plattform erlaubt Schülern nicht, Zeiten zu buchen, die in Ihrem Kalender als belegt markiert sind.',
  'orgTutorPolicy.s2Security': 'Kontosicherheit: Ihr Konto ist persönlich. Sie müssen Ihre Zugangsdaten sicher aufbewahren und dürfen sie nicht an Dritte weitergeben.',
  'orgTutorPolicy.s3Title': '3. Unterrichtsabsagen und Warteliste',
  'orgTutorPolicy.s3Intro': 'Die Plattform hilft Ihnen, Ihren Stundenplan optimal auszulasten und Lücken zu vermeiden:',
  'orgTutorPolicy.s3Auto': 'Wenn ein Schüler eine Stunde absagt, sendet die Plattform automatisch eine Benachrichtigung (SMS/E-Mail) an andere Schüler auf Ihrer Warteliste und bietet den freigewordenen Termin an. Von Ihrer Seite sind keine zusätzlichen Maßnahmen erforderlich.',
  'orgTutorPolicy.s3Rules': 'Die Regeln für Unterrichtsabsagen (wie weit im Voraus abgesagt werden kann, Konsequenzen) werden von Ihrer Organisation festgelegt.',
  'orgTutorPolicy.s4Title': '4. Finanzen und Zahlungen',
  'orgTutorPolicy.s4Intro': 'Sie müssen sich nicht um die Rechnungsstellung oder den Zahlungseinzug bei Eltern kümmern:',
  'orgTutorPolicy.s4Advance': 'Alle Zahlungen der Schüler (oder Eltern) für Ihren Unterricht werden im Voraus über die Plattform eingezogen und direkt an Ihre Organisation überwiesen.',
  'orgTutorPolicy.s4Confirmed': 'Sie erteilen Unterricht erst, wenn er im System bestätigt ist (d. h. die Gebühr wurde bereits abgebucht).',
  'orgTutorPolicy.s4Contact': 'Für Ihr Gehalt, den Auszahlungsplan und andere Finanzfragen wenden Sie sich bitte direkt an den Administrator Ihrer Organisation. MB Tutlio führt keine direkten finanziellen Transaktionen mit Lehrkräften durch.',
  'orgTutorPolicy.s5Title': '5. Schutz der Schülerdaten (DSGVO)',
  'orgTutorPolicy.s5Intro': 'Als Lehrkraft haben Sie Zugang zu personenbezogenen Daten der Schüler, internen Notizen und Lernmaterialien. Sie verpflichten sich:',
  'orgTutorPolicy.s5Use': 'Diese Daten ausschließlich zur Organisation und Durchführung des Unterrichts zu verwenden.',
  'orgTutorPolicy.s5NoCopy': 'Die Kontaktdaten von Schülern oder Eltern nicht außerhalb der Plattform zu kopieren, exportieren oder zu verbreiten.',
  'orgTutorPolicy.s5Notes': 'Interne Aufzeichnungen der Organisation (Notizen zum Lernfortschritt der Schüler), die nur für Sie und die Verwaltung der Organisation sichtbar sind und nicht für Schüler oder Eltern, zu schützen.',
  'orgTutorPolicy.s5Termination': 'Nach Beendigung Ihres Arbeitsverhältnisses mit der Organisation wird Ihr Zugang zu diesen Daten unverzüglich entzogen.',
  'orgTutorPolicy.s6Title': '6. Technischer Betrieb und Haftungsbeschränkung',
  'orgTutorPolicy.s6Body': 'Die Nutzung der Plattform zu rechtswidrigen Zwecken, die Verbreitung bösartiger Links in Unterrichtsmaterialien oder sonstige Störungen des Systems sind untersagt. MB Tutlio gewährleistet den Betrieb und die technische Wartung der Plattform, übernimmt jedoch keine Haftung für Störungen, die durch Ihre Internetverbindung, Geräteausfälle oder falsch konfigurierte Google-Calendar-Einstellungen verursacht werden.',
  'orgTutorPolicy.s7Title': '7. Support und Kontakt',
  'orgTutorPolicy.s7Org': 'Bei Fragen zu Stundenplänen, Gehalt, Schülerzuweisungen oder Arbeitsorganisation wenden Sie sich an den Administrator Ihrer Organisation.',
  'orgTutorPolicy.s7Tech': 'Bei technischen Fehlern der Plattform (Kalender-Synchronisierung funktioniert nicht, Sie erhalten keine Benachrichtigungen) informieren Sie den Administrator Ihrer Organisation, der das technische Support-Team von Tutlio kontaktieren wird.',

