  'feature.cancellation.pageTitle': 'Stornierungsregeln und Gebühren für späte Stornierung für Lehrer',
  'feature.cancellation.pageDesc': 'Legen Sie klare Stornierungsfristen und automatische Gebühren für späte Stornierungen fest. Wenn Schüler stornieren, gehen frei gewordene Termine direkt auf Ihre Warteliste.',
  'feature.cancellation.detailsTitle': 'So funktionieren Stornierungsregeln',
  'feature.cancellation.deadlines': 'Stornierungsfristen',
  'feature.cancellation.deadlinesDesc': 'Legen Sie fest, wie weit im Voraus Schüler stornieren müssen (z. B. 24 Stunden vor der Stunde), um eine Stornierungsgebühr zu vermeiden.',
  'feature.cancellation.fees': 'Automatische Gebühren für späte Stornierung',
  'feature.cancellation.feesDesc': 'Legen Sie eine prozentuale Gebühr fest (z. B. 50 % des Stundenpreises), die automatisch angewendet wird, wenn ein Schüler zu spät storniert.',
  'feature.cancellation.transparency': 'Klare Kommunikation mit Schülern',
  'feature.cancellation.transparencyDesc': 'Schüler sehen Ihre Stornierungsrichtlinie direkt bei der Buchung. Keine Überraschungen — nur professionelle, faire Regeln.',
  'feature.cancellation.waitlistLink': 'Wartelisten-Integration',
  'feature.cancellation.waitlistLinkDesc': 'Stornierte Termine werden sofort den Schülern auf der Warteliste angeboten, damit Ihr Zeitplan voll bleibt und Ihre Einnahmen geschützt sind.',
  'feature.cancellation.faq.howSetQ': 'Wie lege ich Stornierungsregeln fest?',
  'feature.cancellation.faq.howSetA': 'Gehen Sie zu Ihren Stundeneinstellungen und legen Sie die Stornierungsfrist (Stunden vor der Stunde) und den Prozentsatz der Gebühr für späte Stornierung fest. Das System wendet diese automatisch an.',
  'feature.cancellation.faq.refundQ': 'Was passiert mit der Stornierungsgebühr?',
  'feature.cancellation.faq.refundA': 'Gebühren für späte Stornierung werden automatisch berechnet und dem Guthaben des Schülers hinzugefügt. Sie können alle Gebühren in Ihrem Finanz-Dashboard verfolgen.',
  'feature.cancellation.faq.studentSeeQ': 'Sehen Schüler die Stornierungsrichtlinie?',
  'feature.cancellation.faq.studentSeeA': 'Ja, Ihre Stornierungsbedingungen werden den Schülern während der Buchung angezeigt, damit sie die Regeln vor der Bestätigung kennen.',
  'feature.comments.pageTitle': 'Unterrichtsnotizen, Kommentare und Dateifreigabe für Lehrer',
  'feature.comments.pageDesc': 'Fügen Sie einzelnen Stunden Notizen, Hausaufgaben und Dateien hinzu. Erstellen Sie eine vollständige Stundenhistorie, auf die Schüler und Eltern jederzeit zugreifen können.',
  'feature.comments.detailsTitle': 'So funktionieren Unterrichtsnotizen',
  'feature.comments.lessonNotes': 'Notizen pro Stunde',
  'feature.comments.lessonNotesDesc': 'Fügen Sie jeder Stunde private oder geteilte Notizen hinzu — verfolgen Sie, was behandelt wurde, den Fortschritt des Schülers und die nächsten Schritte.',
  'feature.comments.fileSharing': 'Dateianhänge',
  'feature.comments.fileSharingDesc': 'Laden Sie Arbeitsblätter, Hausaufgaben-PDFs oder Lernmaterialien hoch und hängen Sie sie für einfachen Zugriff direkt an eine Stunde an.',
  'feature.comments.history': 'Vollständige Stundenhistorie',
  'feature.comments.historyDesc': 'Jede Notiz und Datei ist mit der zugehörigen Stunde verknüpft und erstellt eine durchsuchbare Zeitleiste des Lernwegs jedes Schülers.',
  'feature.comments.parentAccess': 'Einsicht für Eltern',
  'feature.comments.parentAccessDesc': 'Eltern können geteilte Unterrichtsnotizen und Dateien in ihrem Portal sehen und bleiben so über den Fortschritt ihres Kindes informiert.',
  'feature.comments.faq.whoSeesQ': 'Wer kann Unterrichtsnotizen sehen?',
  'feature.comments.faq.whoSeesA': 'Sie entscheiden, was Sie teilen. Notizen können privat (nur für den Lehrer) oder mit dem Schüler und seinen Eltern geteilt werden.',
  'feature.comments.faq.fileTypesQ': 'Welche Dateitypen kann ich hochladen?',
  'feature.comments.faq.fileTypesA': 'Sie können PDFs, Bilder und gängige Dokumentformate hochladen. Dateien werden sicher gespeichert und sind von jedem Gerät aus zugänglich.',
  'feature.comments.faq.storageQ': 'Gibt es ein Speicherlimit?',
  'feature.comments.faq.storageA': 'Alle Tarife enthalten großzügigen Dateispeicher. Es gibt keine Begrenzung pro Datei — hängen Sie so viele Materialien an, wie Sie benötigen.',
