  'feature.digital-business-card.instantEnquiriesDesc': 'Eltern oder Schüler wählen Stunde, Format und Termin aus und hinterlassen ihre Kontaktdaten. Sie erhalten die vollständige Anfrage ohne aufwendige Terminabstimmung.',
  'feature.digital-business-card.professionalBrand': 'Ein professioneller erster Eindruck',
  'feature.digital-business-card.professionalBrandDesc': 'Zeigen Sie Ihr Foto, Ihren Unterrichtsansatz, Ihre Fächer, Preise, verifizierten Bewertungen und Markenfarben auf einer Seite, die auf jedem Smartphone überzeugt.',
  'feature.digital-business-card.faq.whatShowsQ': 'Was kann ich auf meiner digitalen Visitenkarte zeigen?',
  'feature.digital-business-card.faq.whatShowsA': 'Sie können Ihr Profil, Ihre Fächer, Unterrichtsformate, öffentlichen Preise, freien Termine, Ihren Standort, Sprachen, Social-Media-Links und verifizierte Bewertungen von Schülern präsentieren.',
  'feature.digital-business-card.faq.howBookingWorksQ': 'Bucht ein Interessent sofort einen verbindlichen Termin?',
  'feature.digital-business-card.faq.howBookingWorksA': 'Der Interessent wählt eine Stunde und einen freien Termin aus und sendet anschließend eine vollständige Buchungsanfrage. Sie erhalten die Anfrage in Tutlio und können den neuen Schüler bestätigen, bevor die Stunde in Ihren Kalender aufgenommen wird.',
  'feature.digital-business-card.faq.whereShareQ': 'Wo sollte ich die Seite teilen?',
  'feature.digital-business-card.faq.whereShareA': 'Teilen Sie sie auf Instagram, TikTok, in Facebook-Gruppen, Anzeigen, E-Mail-Signaturen, Nachrichten und QR-Codes. Der Link bleibt aktuell, auch wenn sich Ihre Preise oder Ihr Kalender ändern.',
  'feature.digital-business-card.demo.eyebrow': 'Interaktive Vorschau für Interessenten',
  'feature.digital-business-card.demo.title': 'Testen Sie den Anfrageprozess',
  'feature.digital-business-card.demo.desc': 'Wählen Sie unten eine Stunde und einen Termin aus. Genauso einfach stellen neue Interessenten über Ihren geteilten Link eine Anfrage.',
